 * - variant "full": símbolo + wordmark + subtítulo «Clínica de podología»
 * - variant "lockup": símbolo + wordmark (sin subtítulo)
 * - variant "symbol": solo la huella
 * - variant "wordmark": solo "VALDEPODO"
 */
