  symbol: '720 195 605 1260',
  wordmark: '425 1535 1195 136',
}

const showSymbol = computed(() => props.variant !== 'wordmark')
const showWordmark = computed(() => props.variant !== 'symbol')
const showSubtitle = computed(() => props.variant === 'full')
